1	// How the MHPCO settles a claim against a policy: what the policy covers in
2	// total, and what it will pay out. This is settlement policy, separate from
3	// the premium policy that decides what the office charges.
4	
5	import { ClaimOfficeRefusal } from "./claim-office-refusal.js";
6	import { type Item, insuranceValue } from "./item-catalogue.js";
7	
8	const CAP_MULTIPLE = 2;
9	const DEDUCTIBLE = 100;
10	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
11	const REDUCED_REIMBURSEMENT_RATE = 0.5;
12	
13	// The insurance sum is the sum of the insured items' insurance values; the
14	// block discount affects the premium only, never the insurance sum.
15	export function insuranceSum(items: Item[]): number {
16	  return items.reduce((total, item) => total + insuranceValue(item), 0);
17	}
18	
19	// The total payout per policy is capped at twice the insurance sum.
20	export function policyCap(items: Item[]): number {
21	  return insuranceSum(items) * CAP_MULTIPLE;
22	}
23	
24	export interface Damage {
25	  itemType: string;
26	  amount: number;
27	}
28	
29	export interface Settlement {
30	  payout: number;
31	  remainingCap: number;
32	}
33	
34	// Damage to an item enchanted at this level or above is reimbursed at half.
35	function isReducedReimbursement(item: Item): boolean {
36	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT;
37	}
38	
39	// The reimbursement clauses decide what a damage is worth before the
40	// deductible is withheld. Dragon material is fully reimbursed, which is also
41	// the default for an item no clause reduces, so it needs no separate branch:
42	// where dragon material meets high enchantment the spec's examples give the
43	// 50 % rule precedence (dragon sword, enchantment 8 or 9, damage 1000 G ->
44	// payout 400 G).
45	function reimbursableAmount(item: Item, damage: Damage): number {
46	  return isReducedReimbursement(item)
47	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
48	    : damage.amount;
49	}
50	
51	// A deductible is withheld per damage event, after the reimbursement clauses
52	// have decided what the damage is worth.
53	function damagePayout(item: Item, damage: Damage): number {
54	  return reimbursableAmount(item, damage) - DEDUCTIBLE;
55	}
56	
57	// Admitting an incident's damages to the policy's cover. A damage report names
58	// only an item type, so the office has to decide which covered item each report
59	// refers to -- and refuses the whole claim when the policy covers no such item.
60	// Each damage consumes one covered item, so a policy covering one sword answers
61	// for one damaged sword and no more. This admission is the office's coverage
62	// policy; what an admitted damage is then worth is the reimbursement policy
63	// above, and the two change apart.
64	function admitDamage(unclaimedItems: Item[], damage: Damage): Item {
65	  const covered = unclaimedItems.findIndex(
66	    (item) => item.type === damage.itemType,
67	  );
68	  if (covered < 0) {
69	    throw new ClaimOfficeRefusal(
70	      `the policy does not cover a further item of type ${damage.itemType}`,
71	    );
72	  }
73	  return unclaimedItems.splice(covered, 1)[0];
74	}
75	
76	// Every damage in an incident is settled on its own -- two damaged swords are
77	// two damage events, each bearing its own deductible -- and the claim pays out
78	// the sum of them.
79	function claimPayout(items: Item[], damages: Damage[]): number {
80	  const unclaimedItems = [...items];
81	  return damages.reduce(
82	    (total, damage) =>
83	      total + damagePayout(admitDamage(unclaimedItems, damage), damage),
84	    0,
85	  );
86	}
87	
88	// The total payout per policy is capped, so the office never pays more than
89	// the cap the policy has left: a claim that wants more is reduced to it.
90	function payoutWithinRemainingCap(
91	  desiredPayout: number,
92	  remainingCap: number,
93	): number {
94	  return Math.min(desiredPayout, remainingCap);
95	}
96	
97	// Amounts are rounded to whole G in the MHPCO's favour: a payout is rounded
98	// down. Intermediate amounts are kept as fractions.
99	function roundPayoutInMhpcoFavor(payout: number): number {
100	  return Math.floor(payout);
101	}
102	
103	// Settling a claim: what the incident is worth, reduced to what the policy's
104	// cap still permits, and what that leaves of the cap for later claims.
105	export function settleClaim(
106	  items: Item[],
107	  damages: Damage[],
108	  remainingCap: number,
109	): Settlement {
110	  const desiredPayout = claimPayout(items, damages);
111	  const permittedPayout = payoutWithinRemainingCap(desiredPayout, remainingCap);
112	  const payout = roundPayoutInMhpcoFavor(permittedPayout);
113	  return { payout, remainingCap: remainingCap - payout };
114	}
